import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"System Status","description":"","frontmatter":{},"headers":[],"relativePath":"development/platform/system_status.md","filePath":"versions/development/platform/system_status.md","lastUpdated":1795112498000}'),n={name:"development/platform/system_status.md"};function r(i,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="system-status" tabindex="-1">System Status <a class="header-anchor" href="#system-status" aria-label="Permalink to &quot;System Status&quot;">​</a></h1><p>The <strong>System Status</strong> page is available from the prokube user menu. It shows workspace pod quota for workspaces you can access. For administrators, it also shows the installed platform version and edition, live backend component health checks, the state of live UI updates, and Agent Gateway traffic that is not tied to an API key.</p><p>Use this page to inspect pod quota pressure before starting new workloads, clean up completed pipeline pods, and perform a quick platform health check when you have administrator privileges.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><p>Open the user menu in the prokube UI and select <strong>System Status</strong>.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-user-menu.png" alt="System Status in the user menu" loading="lazy"></p><p>The page may also be available directly at <code>/system-status</code>.</p><p>All authenticated users can open the page to inspect workspace pod quota. The <strong>Platform Information</strong>, <strong>Component Health</strong>, <strong>Realtime Operations</strong>, <strong>Agent Gateway traffic</strong>, and <strong>Backend Info</strong> sections are visible only to realm administrators.</p><h2 id="workspace-pod-quota" tabindex="-1">Workspace Pod Quota <a class="header-anchor" href="#workspace-pod-quota" aria-label="Permalink to &quot;Workspace Pod Quota&quot;">​</a></h2><p>The top section shows pod quota usage across all workspaces you can access. Each workspace card shows:</p><ul><li>workspace name;</li><li>your workspace role;</li><li>pod quota usage, when loaded;</li><li>running pod count;</li><li>pending pod count;</li><li>completed pipeline pod count;</li><li>warning or critical state when usage approaches or exceeds the quota.</li></ul><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-quota-overview.png" alt="Workspace pod quota overview" loading="lazy"></p><p>To keep the page responsive, quota details are not loaded for every workspace at once. The currently selected workspace is loaded automatically when it is in your accessible workspace list. If the selected workspace is not available, the first visible workspace card is loaded. Other workspace cards show <strong>Load pod quota</strong> until you load them manually.</p><p>Use <strong>Refresh</strong> on a workspace card to update that workspace&#39;s quota numbers on demand. If you have many workspaces, use <strong>Load more workspaces</strong> to show additional cards.</p><h2 id="clean-up-completed-pipeline-pods" tabindex="-1">Clean Up Completed Pipeline Pods <a class="header-anchor" href="#clean-up-completed-pipeline-pods" aria-label="Permalink to &quot;Clean Up Completed Pipeline Pods&quot;">​</a></h2><p>When a workspace has completed pipeline pods, the workspace card can show <strong>Clean up completed pipeline pods</strong>.</p><p>This action deletes completed Argo Workflows / Kubeflow Pipelines pod resources in that workspace. It does not delete running pods, pending pods, unrelated pods, pipeline metadata, artifacts, or logs.</p><p>Use this when completed pipeline pods are consuming workspace pod quota and blocking new work.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-cleanup-dialog.png" alt="Delete Completed Pipeline Pods dialog" loading="lazy"></p><h2 id="platform-information" tabindex="-1">Platform Information <a class="header-anchor" href="#platform-information" aria-label="Permalink to &quot;Platform Information&quot;">​</a></h2><p>Realm administrators see the installed prokube version, the edition, and the installation registration status.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-platform-information-framed.png" alt="Platform Information with prokube version, edition, and registration status" loading="lazy"></p><p>On the Core edition, the section is titled <strong>Platform &amp; Subscription</strong> and also shows the subscription status, its validity and grace dates, and the <strong>Installation ID</strong>.</p><h3 id="register-the-installation" tabindex="-1">Register the Installation <a class="header-anchor" href="#register-the-installation" aria-label="Permalink to &quot;Register the Installation&quot;">​</a></h3><p>When the installation is <strong>Not registered</strong>, the section shows <strong>Register this installation</strong>. Enter the <strong>Organization</strong> and a <strong>Contact email</strong>, accept the privacy statement, and select <strong>Submit registration</strong>. prokube.ai reviews the request manually; the status changes to <strong>Pending</strong>, then <strong>Approved</strong> or <strong>Rejected</strong>. After a rejection you can submit corrected details.</p><p>Registration does not change the edition. The installation stays on Demo until prokube.ai assigns Core or Enterprise. prokube.ai uses the contact details only to review and manage the registration. <strong>Status unavailable</strong> means that registration is not available from this cluster.</p><h2 id="admin-component-health" tabindex="-1">Admin Component Health <a class="header-anchor" href="#admin-component-health" aria-label="Permalink to &quot;Admin Component Health&quot;">​</a></h2><p>Realm administrators also see <strong>Component Health</strong>. This section runs live health checks against backend components and shows whether platform services are healthy, degraded, unhealthy, or disabled.</p><p>Each component card includes:</p><ul><li>component name;</li><li>health state;</li><li>check latency in milliseconds when the component is enabled;</li><li>a short detail message from the health check.</li></ul><p>Possible states:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Healthy</strong></td><td>The component is enabled and responded successfully.</td></tr><tr><td><strong>Degraded</strong></td><td>The component responded, but the check found a non-fatal issue.</td></tr><tr><td><strong>Unhealthy</strong></td><td>The component is enabled but failed its health check.</td></tr><tr><td><strong>Disabled</strong></td><td>The component is not enabled in the current deployment.</td></tr></tbody></table><p>The summary bar counts healthy, degraded, unhealthy, and disabled components.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-admin-health.png" alt="Admin Component Health" loading="lazy"></p><h2 id="realtime-operations" tabindex="-1">Realtime Operations <a class="header-anchor" href="#realtime-operations" aria-label="Permalink to &quot;Realtime Operations&quot;">​</a></h2><p>Check <strong>Realtime Operations</strong> when the Volumes, Labs, Models, or LLM Serving pages show outdated state. It shows whether the platform delivers live updates to these pages; when live updates fail, the pages fall back to polling and can lag behind the cluster. Only realm administrators see this section.</p><p>The badge at the top shows the overall state:</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>healthy</strong></td><td>Live updates work.</td></tr><tr><td><strong>reconnecting</strong></td><td>The connection to the Kubernetes API dropped. Cached data is still recent enough to use.</td></tr><tr><td><strong>recovering</strong></td><td>Data is being reloaded from the Kubernetes API. Cached data is still usable.</td></tr><tr><td><strong>stale</strong></td><td>Cached data is too old to use. Pages may show outdated state.</td></tr><tr><td><strong>capacity limited</strong></td><td>A connection, buffer, or watch limit is reached. New connections or updates can be rejected.</td></tr><tr><td><strong>unavailable</strong></td><td>The realtime service is not reachable, or the feature is not deployed.</td></tr></tbody></table><p><strong>Family cache health</strong> shows the state and reason for each page; it lists Labs as <strong>Dev Labs</strong>, Models as <strong>KServe</strong>, and LLM Serving as <strong>LLM</strong>. The remaining panels show connection counts, limits, and counters such as reconnects and drops. Counters run from the last restart of the realtime service, shown as <strong>Process generation</strong>, so compare them over time: counters that keep rising point to a current problem.</p><p><strong>Current admin browser</strong> reflects only your own browser tab: whether it receives live updates and whether its pages recently fell back to polling.</p><h3 id="troubleshoot-live-updates" tabindex="-1">Troubleshoot Live Updates <a class="header-anchor" href="#troubleshoot-live-updates" aria-label="Permalink to &quot;Troubleshoot Live Updates&quot;">​</a></h3><ol><li>Select <strong>Run All Checks</strong> to refresh the panel, or enable <strong>Auto-refresh</strong>.</li><li>If a state stays <strong>reconnecting</strong>, <strong>recovering</strong>, or <strong>stale</strong>, check the reason under <strong>Family cache health</strong>. Then check that the realtime service is ready and that the Kubernetes API is reachable and responsive.</li><li>If the state is <strong>capacity limited</strong>, find the limit that is reached under <strong>Transport</strong> or <strong>Diagnostics Event watches</strong>, and check whether drops keep increasing.</li><li>If only <strong>Current admin browser</strong> is disconnected, reload the page or sign in again.</li></ol><h2 id="agent-gateway-traffic" tabindex="-1">Agent Gateway Traffic <a class="header-anchor" href="#agent-gateway-traffic" aria-label="Permalink to &quot;Agent Gateway Traffic&quot;">​</a></h2><p>If the API Keys feature is installed, realm administrators also see <strong>Agent Gateway traffic</strong>. It covers calls in all workspaces that are not tied to an API key or model grant. Usage by API key and model grant is shown per workspace on <a href="./gateway_usage.html">Gateway Usage</a>, and LLM spend across all workspaces on <a href="./../admin/llm_usage.html">LLM Usage and Cost</a>.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-agent-gateway-traffic-framed.png" alt="Agent Gateway traffic with internal, token, and failed calls, calls without valid credentials, the call trend, and top routes" loading="lazy"></p><p>Select <strong>Last hour</strong>, <strong>Last 24 hours</strong> (default), <strong>Last 7 days</strong>, or <strong>Max (N days)</strong>. The panel shows:</p><ul><li><strong>Internal calls</strong>: keyless calls between platform services inside the cluster, for example agents calling self-hosted models or MCP servers. See <a href="./agent_gateway.html#public-vs-internal-traffic">Public vs. Internal Traffic</a>.</li><li><strong>Token calls</strong>: calls signed in with a user account or with a workspace notebook or pipeline token, for example to sandboxes. A token call can still fail after sign-in.</li><li><strong>Calls without valid credentials</strong>: calls with a missing or invalid API key or token. Most are rejected with <code>401</code>.</li><li><strong>Failed calls</strong>: failed calls across the three classes above.</li><li><strong>Top routes</strong>: the routes that received the most of these calls, with their class and failures. Background calls by platform controllers, such as kagent discovering MCP tools, are left out of the totals and can be shown with <strong>Show</strong>.</li></ul><p>A sudden rise in calls without valid credentials usually means a client still uses a revoked or rotated key. If usage telemetry is not available, the panel says so instead of showing zero.</p><h2 id="admin-backend-info" tabindex="-1">Admin Backend Info <a class="header-anchor" href="#admin-backend-info" aria-label="Permalink to &quot;Admin Backend Info&quot;">​</a></h2><p>Realm administrators also see <strong>Backend Info</strong>, including backend version and enabled backend modules.</p><p>Use this to confirm which backend version and modules are active in the current deployment before debugging feature behavior.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/platform/system-status/system-status-backend-info.png" alt="Backend Info" loading="lazy"></p><h2 id="refresh-checks" tabindex="-1">Refresh Checks <a class="header-anchor" href="#refresh-checks" aria-label="Permalink to &quot;Refresh Checks&quot;">​</a></h2><p>Click <strong>Run All Checks</strong> to rerun administrator health checks manually.</p><p>Enable <strong>Auto-refresh</strong> when you want the page to rerun checks periodically while watching a rollout or investigating an incident. Auto-refresh runs every 30 seconds and also updates Realtime Operations. Neither control refreshes the workspace quota cards.</p><p>Use manual refresh for normal checks. Use auto-refresh only while actively monitoring; for long-running observability, use Grafana, Prometheus, and alerting instead.</p><h2 id="recommended-workflow" tabindex="-1">Recommended Workflow <a class="header-anchor" href="#recommended-workflow" aria-label="Permalink to &quot;Recommended Workflow&quot;">​</a></h2><p>When a user reports that workloads cannot start:</p><ol><li>Open <strong>System Status</strong> from the user menu.</li><li>Check the workspace pod quota card for the affected workspace.</li><li>If completed pipeline pods are consuming quota, clean them up from the workspace card.</li><li>If you are an administrator, run <strong>Component Health</strong> checks.</li><li>Use unhealthy or degraded component messages as a starting point, then continue in Grafana, Loki, Argo CD, Kubernetes events, or pod logs.</li></ol><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Workspace pod quota cards show only workspaces you can access.</li><li>Quota details are loaded per workspace, not all at once.</li><li>Platform Information, component health checks, Realtime Operations, and Agent Gateway traffic are administrator-only.</li><li>The page checks backend components and integrations, not every workload in every workspace.</li><li>A healthy component status means the health check passed; it does not guarantee that all user workflows are healthy.</li><li>A disabled status can be expected when a module is intentionally not enabled in a deployment.</li><li>Detailed historical metrics, alerts, and logs remain in Grafana, Prometheus, Alertmanager, and Loki.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./kubernetes.html">Kubernetes Resources</a></li><li><a href="./observability.html">Observability</a></li><li><a href="./../mlops/pipelines.html">Pipelines</a></li><li><a href="./../admin/">Admin Documentation</a></li></ul>',63)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
